import * as vscode from 'vscode';
import * as clipboard from 'clipboardy';

export function activate(context: vscode.ExtensionContext) {
    console.log('Congratulations, your extension "my-first-extension" is now active!');

    // Store the previous clipboard content to compare for changes
    let previousClipboardContent = '';

    // Function to check clipboard content
    const checkClipboard = async () => {
        try {
            const currentContent = await vscode.env.clipboard.readText();

            // Only process if content has changed
            if (currentContent !== previousClipboardContent) {
                console.log(`Clipboard changed: ${currentContent.substring(0, 50)}${currentContent.length > 50 ? '...' : ''}`);

                // Update previous content
                previousClipboardContent = currentContent;

                // You can add custom logic here to handle clipboard changes
                // For example, validate content, transform text, etc.

                // Optional: Show a notification
                // vscode.window.showInformationMessage(`Clipboard updated: ${currentContent.substring(0, 30)}...`);
            }
        } catch (error) {
            console.error('Error reading clipboard:', error);
        }
    };

    // Set up clipboard monitoring with a timer
    // Check every 2 seconds for clipboard changes
    const clipboardInterval = setInterval(checkClipboard, 2000);

    // Initial check
    checkClipboard();

    // Register a command to manually check clipboard
    let disposable = vscode.commands.registerCommand('my-first-extension.helloWorld', () => {
        vscode.window.showInformationMessage('Hello World from my-first-extension!');
    });

    // Clean up the interval when the extension is deactivated
    context.subscriptions.push({
        dispose: () => {
            if (clipboardInterval) {
                clearInterval(clipboardInterval);
            }
        }
    });

    context.subscriptions.push(disposable);
}

export function deactivate() {
    // This method is called when the extension is deactivated
    // Clean up any resources
    console.log('Extension deactivated');
}

