// Check if the clipboard content matches common API key patterns
const apiKeyPatterns = [
    // AWS Access Key - 20 characters, uppercase letters and numbers, starting with AKIA, AIDA, AGPA, AROA, AROA, AIPA, ANPA, ANVA, ASIA
    /(?:AKIA|AIDA|AGPA|AROA|AIPA|ANPA|ANVA|ASIA)[A-Z0-9]{16}/,

    // Google API Key - 39 characters, starts with AIza, contains letters, numbers, and underscores/dashes
    /AIza[0-9A-Za-z-_]{35}/,

    // GitHub Token - typically starts with ghp_, ghs_, gpr_, ghp- (40 characters)
    /ghp_[0-9a-zA-Z]{36}/,
    /ghs_[0-9a-zA-Z]{36}/,
    /gpr_[0-9a-zA-Z]{36}/,
    /github_pat_[0-9A-Za-z_]{68}/,

    // Stripe Keys - starts with sk_live_ or rk_live_
    /sk_live_[0-9a-zA-Z]{24}/,
    /rk_live_[0-9a-zA-Z]{24}/,

    // Generic UUID format (common in API keys)
    /[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}/,

    // Azure API Key - 32-64 characters, often base64 encoded
    /[a-zA-Z0-9+\/]{32,64}={0,2}/,

    // Generic API key - 32-64 alphanumeric characters
    /[A-Za-z0-9]{32,64}/
];

// Test the current clipboard content against all API key patterns
const isApiKey = apiKeyPatterns.some(pattern => pattern.test(currentContent));

if (isApiKey) {
    console.log('Potential API key detected in clipboard!');

    // Show a warning notification to the user
    vscode.window.showWarningMessage(
        'Potential API key detected in clipboard!', 
        'Learn More', 
        'Dismiss'
    ).then(selection => {
        if (selection === 'Learn More') {
            vscode.env.openExternal(vscode.Uri.parse('https://owasp.org/www-community/vulnerabilities/Information_exposure_through_an_error_message'));
        }
    });

    // You could also implement additional security measures here:
    // - Copy a redacted version back to clipboard
    // - Log the event for security auditing
    // - Trigger a security workflow
}

