console.log('Potential API key detected in clipboard!');

// Create audit log entry with timestamp and redacted key
const now = new Date();
const redactedKey = currentContent.length > 8 
    ? currentContent.substring(0, 4) + '*'.repeat(16) + currentContent.slice(-4)
    : '*'.repeat(currentContent.length);

const logEntry = `${now.toISOString()} - Potential API key detected - Redacted: ${redactedKey} - Length: ${currentContent.length}\n`;

// Write to hidden audit log file
const logUri = vscode.Uri.joinPath(context.extensionUri, '.audit-log');

// Check if file exists, then append to it
vscode.workspace.fs.stat(logUri).then(
    () => {
        // File exists, read current content and append
        return vscode.workspace.fs.readFile(logUri).then(content => {
            const updatedContent = Buffer.concat([
                content,
                Buffer.from(logEntry)
            ]);
            return vscode.workspace.fs.writeFile(logUri, updatedContent);
        });
    },
    () => {
        // File doesn't exist, create it with header
        const header = '# API Key Detection Audit Log\n# Format: ISO Timestamp - Event - Redacted Key - Length\n# Keys are redacted for security (first 4 chars + ****** + last 4 chars)\n\n';
        return vscode.workspace.fs.writeFile(logUri, Buffer.from(header + logEntry));
    }
).then(() => {
    console.log('Audit log updated');
}).catch(err => {
    console.error('Failed to write to audit log:', err);
});

// Show a warning notification to the user
vscode.window.showWarningMessage(
    'Potential API key detected in clipboard!', 
    'Learn More', 
    'Dismiss'
).then(selection => {
